function updateVideo(currentStatus: string, timeUploaded: number, videoName: string): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    setTimeout(() => {
      if (currentStatus === "In draft") {
        resolve(`Succesfully updated video ${videoName}`);
      } else if (currentStatus === "Published" && timeUploaded < 100) {
        reject(`Video ${videoName} hasn't been uploaded long enough to update.`);
      } else {
        resolve(`Published video ${videoName} updated.`);
      }
    }, 500);
  });
}
